import 'package:flutter/foundation.dart';
import 'package:omnix/features/receipt/controller/printer_settings_controller.dart';
import 'package:omnix/features/receipt/model/receipt_document.dart';
import 'package:omnix/features/receipt/printer/receipt_pdf_builder.dart';
import 'package:omnix/features/receipt/printer/receipt_printer.dart';
import 'package:pdf/pdf.dart';
import 'package:printing/printing.dart';

/// Sends the invoice to a Windows printer queue (USB thermal printer).
///
/// The PDF is generated by [ReceiptPdfBuilder] and handed to the spooler with
/// [Printing.directPrintPdf], which prints without opening the system dialog.
class SpoolReceiptPrinter implements ReceiptPrinter {
  SpoolReceiptPrinter({required this.settings});

  final PrinterSettingsController settings;

  @override
  Future<ReceiptPrintResult> printReceipt(
    ReceiptDocument document, {
    String? qrData,
  }) async {
    try {
      final Uint8List bytes = await ReceiptPdfBuilder.build(
        document: document,
        qrData: qrData,
        copies: settings.copies.value,
      );

      return await _send(
        bytes,
        jobName: 'Invoice ${document.invoiceNumber}',
      );
    } catch (error) {
      return ReceiptPrintResult.failure(
        'Could not prepare the print job: $error',
      );
    }
  }

  @override
  Future<ReceiptPrintResult> printTestPage() async {
    try {
      final Printer? printer = await settings.resolvePrinter();
      if (printer == null) {
        return const ReceiptPrintResult.failure(noPrinterMessage);
      }

      final Uint8List bytes = await ReceiptPdfBuilder.buildTestPage(
        printerName: printer.name,
      );

      return await _send(bytes, jobName: 'Printer test', printer: printer);
    } catch (error) {
      return ReceiptPrintResult.failure(
        'Could not print the test page: $error',
      );
    }
  }

  Future<ReceiptPrintResult> _send(
    Uint8List bytes, {
    required String jobName,
    Printer? printer,
  }) async {
    try {
      final Printer? target = printer ?? await settings.resolvePrinter();
      if (target == null) {
        return const ReceiptPrintResult.failure(noPrinterMessage);
      }

      final bool sent = await Printing.directPrintPdf(
        printer: target,
        name: jobName,
        format: PdfPageFormat.roll80,
        onLayout: (PdfPageFormat format) async => bytes,
      );

      if (!sent) {
        return ReceiptPrintResult.failure(
          'The printer "${target.name}" did not accept the job.',
        );
      }

      return ReceiptPrintResult.success(target.name);
    } catch (error) {
      debugPrint('Receipt printing failed: $error');
      return ReceiptPrintResult.failure(
        'Could not reach the printer. Check that it is switched on and connected.',
      );
    }
  }
}
